From 84e77f49a3e4b36651f6f53d0a4346801b949e02 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 02:25:29 +0100
Subject: [PATCH] applet: list devices of a turned off adapter as unavailable

With more than one adapter, paired devices of an adapter that is turned
off were still listed under "Available" although they can't be used. Put
them in their own "Unavailable" section, sorted below available devices.

BUG: 510884
---
 src/applet/devicesproxymodel.cpp | 13 +++++++++++++
 1 file changed, 13 insertions(+)

diff --git a/src/applet/devicesproxymodel.cpp b/src/applet/devicesproxymodel.cpp
index bea49e5c..a0fbe9cf 100644
--- a/src/applet/devicesproxymodel.cpp
+++ b/src/applet/devicesproxymodel.cpp
@@ -66,6 +66,9 @@ QVariant DevicesProxyModel::data(const QModelIndex &index, int role) const
         if (index.data(BluezQt::DevicesModel::ConnectedRole).toBool()) {
             return i18nc("@title:column Connected Bluetooth devices", "Connected");
         }
+        if (!index.data(BluezQt::DevicesModel::AdapterPoweredRole).toBool()) {
+            return i18nc("@title:column Bluetooth devices whose adapter is turned off", "Unavailable");
+        }
         return i18nc("@title:column Available but not connected Bluetooth devices", "Available");

     case DeviceFullNameRole:
@@ -107,6 +110,16 @@ bool DevicesProxyModel::lessThan(const QModelIndex &left, const QModelIndex &rig
         return false;
     }

+    bool leftPowered = left.data(BluezQt::DevicesModel::AdapterPoweredRole).toBool();
+    bool rightPowered = right.data(BluezQt::DevicesModel::AdapterPoweredRole).toBool();
+
+    // Devices of a turned off adapter go below available ones
+    if (!leftPowered && rightPowered) {
+        return true;
+    } else if (leftPowered && !rightPowered) {
+        return false;
+    }
+
     const QString &leftName = left.data(BluezQt::DevicesModel::NameRole).toString();
     const QString &rightName = right.data(BluezQt::DevicesModel::NameRole).toString();

